def r2(feat, Y):
    Xd=np.hstack([np.ones((len(feat),1)),feat])
    coef,*_=np.linalg.lstsq(Xd,Y,rcond=None)
    R=Y-Xd@coef
    return 1-(R**2).sum()/((Y-Y.mean(0))**2).sum(), coef, R
